"""Translation layer: every sentence the system says, in English, Hindi and Kannada.

One table feeds the web console (GET /i18n) and the Telegram alerts, so the numbers
in a translated sentence are always the measured ones (nothing is machine-translated
at run time, and it works with no internet).

To add a language: copy the "en" block, translate the values, add it to LANGS.
Placeholders like {loss} are filled in by t(); keep them unchanged.
"""

LANGS = {"en": "English", "hi": "हिन्दी", "kn": "ಕನ್ನಡ"}

